using namespace std;

std::wstring createHiddenTempDir(){
    char tempPath[MAX_PATH];
    GetTempPathA(MAX_PATH, tempPath);
    std::wstring tempDir = std::wstring(tempPath, tempPath + strlen(tempPath)) + L"autoSFX\\";
    if (!CreateDirectoryW(tempDir.c_str(), NULL) && GetLastError() != ERROR_ALREADY_EXISTS){
        std::wcerr << L"Error: Could not create temporary directory." << std::endl;
        exit(1);
    }
    SetFileAttributesW(tempDir.c_str(), FILE_ATTRIBUTE_HIDDEN);
    return tempDir;
}

